def _verse(bottles):
    if bottles == 0:
        return [
            "No more bottles of beer on the wall, no more bottles of beer.",
            "Go to the store and buy some more, 99 bottles of beer on the wall.",
        ]

    bottle_word = "bottle" if bottles == 1 else "bottles"
    first_line = (
        f"{bottles} {bottle_word} of beer on the wall, "
        f"{bottles} {bottle_word} of beer."
    )

    if bottles == 1:
        second_line = (
            "Take it down and pass it around, "
            "no more bottles of beer on the wall."
        )
    else:
        next_bottles = bottles - 1
        next_word = "bottle" if next_bottles == 1 else "bottles"
        second_line = (
            f"Take one down and pass it around, {next_bottles} "
            f"{next_word} of beer on the wall."
        )

    return [first_line, second_line]


def recite(start, take=1):
    verses = []
    bottles = start

    for verse_number in range(take):
        if verse_number:
            verses.append("")
        verses.extend(_verse(bottles))
        bottles = (bottles - 1) % 100

    return verses

from functools import lru_cache


_GROUP_PRICES = (0, 800, 1520, 2160, 2560, 3000)


def total(basket):
    counts = tuple(basket.count(book) for book in range(1, 6))

    @lru_cache(maxsize=None)
    def cheapest(remaining):
        if not any(remaining):
            return 0

        best = float("inf")
        # A group contains at most one copy of each title.
        for mask in range(1, 1 << 5):
            group_size = mask.bit_count()
            next_remaining = list(remaining)
            for index in range(5):
                if mask & (1 << index):
                    if next_remaining[index] == 0:
                        break
                    next_remaining[index] -= 1
            else:
                best = min(
                    best,
                    _GROUP_PRICES[group_size] + cheapest(tuple(next_remaining)),
                )

        return best

    return cheapest(counts)

